css:
:root {
  --line-default-color: #C2CFD9;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  border: none;
  background: transparent !important;
}

.dotted-line-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.dotted-line-svg {
  display: block;
  width: 100%;
  height: 100%;

  background: transparent;
  shape-rendering: geometricPrecision;
}

.dotted-line-stroke {
  fill: none;

  /* El inspector tiene prioridad sobre el color inicial. */
  stroke: var(--w-color, var(--line-default-color));

  stroke-width: 2;
  stroke-dasharray: 4 8;
  stroke-linecap: round;
}

js:
"use strict";

(function () {
  /*
   * Relación entre el ancho del widget y el grosor:
   *
   * Ancho 40 px  -> grosor 2 px.
   * Ancho 60 px  -> grosor 3 px.
   * Ancho 80 px  -> grosor 4 px.
   * Ancho 100 px -> grosor 5 px.
   *
   * Modifica este factor si deseas otra proporción.
   */
  const THICKNESS_FACTOR = 0.05;

  let container = null;
  let line = null;
  let resizeObserver = null;

  function updateGeometry() {
    if (!container || !line) return;

    const width = container.clientWidth;
    const height = container.clientHeight;

    if (width <= 0 || height <= 0) return;

    const thickness = Math.min(
      Math.max(0.5, width * THICKNESS_FACTOR),
      height
    );

    const centerX = width / 2;
    const endPadding = thickness / 2;

    /*
     * Centra la línea horizontalmente.
     * Reserva espacio para los extremos redondeados.
     */
    line.setAttribute("x1", String(centerX));
    line.setAttribute("x2", String(centerX));
    line.setAttribute("y1", String(endPadding));
    line.setAttribute("y2", String(height - endPadding));

    /*
     * Conserva la proporción del patrón al cambiar
     * el grosor, sin estirar los trazos con la altura.
     */
    line.style.strokeWidth = thickness + "px";

    line.style.strokeDasharray =
      (thickness * 2) + " " + (thickness * 4);
  }

  function initialize() {
    container = document.querySelector(".dotted-line-widget");
    line = document.querySelector(".dotted-line-stroke");

    if (!container || !line) return;

    updateGeometry();

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(updateGeometry);
      resizeObserver.observe(container);
    } else {
      window.addEventListener("resize", updateGeometry);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }

  /*
   * No utiliza variables del PLC.
   *
   * El puente del software actualiza --w-color.
   * La rotación se aplica desde el diseñador al widget
   * completo, para evitar recortar la línea dentro del iframe.
   */
})();
